const d=await page.evaluate(()=>({title:document.title,lang:document.documentElement.lang,h1:[...document.querySelectorAll('h1')].map(h=>h.textContent.trim()),cur:[...document.querySelectorAll('[aria-current="page"]')].map(e=>e.textContent.trim()+'|'+e.getAttribute('href')),header:(document.querySelector('header')||{}).innerText,btn:[...document.querySelectorAll('a,button')].filter(e=>/Lancer la Chaîne/.test(e.textContent)).map(e=>e.closest('header')?'header':'autre'),repli:/Mode repli/.test(document.body.innerText),bandeau:document.body.innerText.slice(0,600)}));
out.push({u,status:resp.status(),...d});}
return {out,reqs:[...new Set(reqs.map(r=>new URL(r).host))]};}

