async (page) => {
await page.goto('http://127.0.0.1:8765/agent');
await page.keyboard.press('Tab');
const f=await page.evaluate(()=>{const e=document.activeElement;const r=e.getBoundingClientRect();return {t:e.textContent.trim(),href:e.getAttribute('href'),x:r.x,y:r.y,w:r.width,h:r.height,outline:getComputedStyle(e).outlineStyle+' '+getComputedStyle(e).outlineWidth}});
await page.keyboard.press('Enter');
const a=await page.evaluate(()=>({hash:location.hash,active:document.activeElement.tagName+':'+document.activeElement.textContent.trim().slice(0,40),h1y:document.querySelector('h1').getBoundingClientRect().y}));
const order=[];
for(let i=0;i<14;i++){await page.keyboard.press('Tab');order.push(await page.evaluate(()=>document.activeElement.textContent.trim().slice(0,30)+'|'+getComputedStyle(document.activeElement).outlineStyle+getComputedStyle(document.activeElement).outlineWidth));}
await page.setViewportSize({width:390,height:844});
const sw=await page.evaluate(()=>[document.documentElement.scrollWidth,innerWidth]);
await page.screenshot({path:'t2.png'});
await page.goto('http://127.0.0.1:8765/outillage');
const sw2=await page.evaluate(()=>[document.documentElement.scrollWidth,innerWidth]);
await page.setViewportSize({width:1280,height:800});
return {f,a,order,sw,sw2};}

